import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form, Button } from "react-bootstrap";

function History() {
  // --- 1. ข้อมูลพื้นฐานสำหรับตัวเลือกแบบไทย ---
  const monthsThai = [
    { val: "01", name: "มกราคม" }, { val: "02", name: "กุมภาพันธ์" },
    { val: "03", name: "มีนาคม" }, { val: "04", name: "เมษายน" },
    { val: "05", name: "พฤษภาคม" }, { val: "06", name: "มิถุนายน" },
    { val: "07", name: "กรกฎาคม" }, { val: "08", name: "สิงหาคม" },
    { val: "09", name: "กันยายน" }, { val: "10", name: "ตุลาคม" },
    { val: "11", name: "พฤศจิกายน" }, { val: "12", name: "ธันวาคม" }
  ];
  
  const currentYearCE = new Date().getFullYear();
  const yearsBE = [currentYearCE + 542, currentYearCE + 543, currentYearCE + 544];
  const hours = Array.from({ length: 24 }, (_, i) => i.toString().padStart(2, '0'));
  const minutes = ["00", "15", "30", "45"];

  // --- 2. State สำหรับเก็บค่าที่เลือก ---
  const [selectedDay, setSelectedDay] = useState(new Date().getDate().toString());
  const [selectedMonth, setSelectedMonth] = useState((new Date().getMonth() + 1).toString().padStart(2, '0'));
  const [selectedYearBE, setSelectedYearBE] = useState((currentYearCE + 543).toString());
  const [startH, setStartH] = useState("07");
  const [startM, setStartM] = useState("00");
  const [endH, setEndH] = useState("22");
  const [endM, setEndM] = useState("00");
  const [cameraId, setCameraId] = useState("CAM01");
  const [data, setData] = useState({ labels: [], series: [] });

  // --- 3. ฟังก์ชันคำนวณจำนวนวันให้สัมพันธ์กับเดือน (Dynamic Days) ---
  const getDaysInMonth = (m, yBE) => {
    const yearCE = parseInt(yBE) - 543;
    return new Date(yearCE, parseInt(m), 0).getDate();
  };

  const daysCount = getDaysInMonth(selectedMonth, selectedYearBE);
  const daysArray = Array.from({ length: daysCount }, (_, i) => (i + 1).toString());

  // ตรวจสอบว่าถ้าเปลี่ยนเดือนแล้ววันที่ที่เลือกเกินจำนวนวันในเดือนนั้น ให้ปัดลงมาวันสุดท้าย
  useEffect(() => {
    if (parseInt(selectedDay) > daysCount) {
      setSelectedDay(daysCount.toString());
    }
  }, [selectedMonth, selectedYearBE, daysCount, selectedDay]);

  // --- 4. ฟังก์ชันดึงข้อมูลจาก API ---
  const handleSearch = async () => {
    const yearCE = parseInt(selectedYearBE) - 543; // แปลง พ.ศ. เป็น ค.ศ. ก่อนส่ง
    const formattedDate = `${yearCE}-${selectedMonth}-${selectedDay.padStart(2, '0')}`;
    const startTime = `${startH}:${startM}:00`;
    const endTime = `${endH}:${endM}:59`;

    try {
      const res = await fetch(
        `http://localhost:3000/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=${startTime}&endTime=${endTime}`
      );
      const result = await res.json();
      
      if (result.labels) {
        // เติม "น." ต่อท้ายเวลาบนกราฟให้คนไทยเข้าใจง่าย
        const thaiLabels = result.labels.map(l => l + " น.");
        setData({ labels: thaiLabels, series: result.series });
      }
    } catch (err) {
      console.error("Fetch Error:", err);
      alert("ไม่สามารถดึงข้อมูลได้ โปรดลองอีกครั้งครับ");
    }
  };

  return (
    <Container fluid>
      <Row>
        <Col md="12">
          <Card>
            <Card.Header>
              <Card.Title as="h4">ตรวจสอบประวัติรายจุด (รูปแบบไทย 24 ชม.)</Card.Title>
            </Card.Header>
            <Card.Body>
              {/* ส่วนเลือกวันที่ พ.ศ. */}
              <Row>
                <Col md="3">
                  <Form.Group>
                    <label>เลือกจุดจอดรถ</label>
                    <Form.Control as="select" value={cameraId} onChange={(e) => setCameraId(e.target.value)}>
                      <option value="CAM01">วิศวะ (CAM01)</option>
                      <option value="CAM02">วิทยาศาสตร์ (CAM02)</option>
                      <option value="CAM03">ศิลปศาสตร์ (CAM03)</option>
                      <option value="CAM04">หอพัก PKY (CAM04)</option>
                    </Form.Control>
                  </Form.Group>
                </Col>
                <Col md="2">
                  <Form.Group>
                    <label>วันที่</label>
                    <Form.Control as="select" value={selectedDay} onChange={(e) => setSelectedDay(e.target.value)}>
                      {daysArray.map(d => <option key={d} value={d}>{d}</option>)}
                    </Form.Control>
                  </Form.Group>
                </Col>
                <Col md="4">
                  <Form.Group>
                    <label>เดือน</label>
                    <Form.Control as="select" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}>
                      {monthsThai.map(m => <option key={m.val} value={m.val}>{m.name}</option>)}
                    </Form.Control>
                  </Form.Group>
                </Col>
                <Col md="3">
                  <Form.Group>
                    <label>ปี พ.ศ.</label>
                    <Form.Control as="select" value={selectedYearBE} onChange={(e) => setSelectedYearBE(e.target.value)}>
                      {yearsBE.map(y => <option key={y} value={y}>{y}</option>)}
                    </Form.Control>
                  </Form.Group>
                </Col>
              </Row>

              {/* ส่วนเลือกเวลา 24 ชม. (ไม่มี AM/PM) */}
              <Row className="mt-3">
                <Col md="3">
                  <Form.Group>
                    <label>ตั้งแต่เวลา (น.)</label>
                    <div className="d-flex align-items-center">
                      <Form.Control as="select" value={startH} onChange={(e) => setStartH(e.target.value)}>
                        {hours.map(h => <option key={h} value={h}>{h}</option>)}
                      </Form.Control>
                      <span className="mx-2">:</span>
                      <Form.Control as="select" value={startM} onChange={(e) => setStartM(e.target.value)}>
                        {minutes.map(m => <option key={m} value={m}>{m}</option>)}
                      </Form.Control>
                    </div>
                  </Form.Group>
                </Col>
                <Col md="3">
                  <Form.Group>
                    <label>ถึงเวลา (น.)</label>
                    <div className="d-flex align-items-center">
                      <Form.Control as="select" value={endH} onChange={(e) => setEndH(e.target.value)}>
                        {hours.map(h => <option key={h} value={h}>{h}</option>)}
                      </Form.Control>
                      <span className="mx-2">:</span>
                      <Form.Control as="select" value={endM} onChange={(e) => setEndM(e.target.value)}>
                        {minutes.map(m => <option key={m} value={m}>{m}</option>)}
                      </Form.Control>
                    </div>
                  </Form.Group>
                </Col>
                <Col md="6" className="d-flex align-items-end">
                  <Button className="btn-fill w-100" variant="info" onClick={handleSearch}>
                    ค้นหาข้อมูลประวัติ
                  </Button>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* กราฟแสดงผล */}
      {data.labels.length > 0 && (
        <Row>
          <Col md="12">
            <Card>
              <Card.Header>
                <Card.Title as="h4">สถิติจำนวนคน: {cameraId}</Card.Title>
                <p className="card-category">
                  ประจำวันที่ {selectedDay} {monthsThai.find(m => m.val === selectedMonth).name} {selectedYearBE} (ช่วงเวลา {startH}:{startM} น. - {endH}:{endM} น.)
                </p>
              </Card.Header>
              <Card.Body>
                <ChartistGraph
                  data={data}
                  type="Line"
                  options={{
                    low: 0,
                    height: "300px",
                    showArea: true,
                    fullWidth: true,
                    axisX: { showGrid: false }
                  }}
                />
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
